156	// ----------------------------------------------------------------------------
157	// Sandbox in-memory filesystem
158	// ----------------------------------------------------------------------------
159	
160	type SimNode =
161	  | { type: "dir"; mtime: number; mode: number; children: Record<string, SimNode> }
162	  | { type: "file"; mtime: number; mode: number; content: string };
163	type SimDir = Extract<SimNode, { type: "dir" }>;
164	
165	/** One simulated filesystem per server id, lazily seeded. */
166	const globalForSim = globalThis as unknown as { __nxeonSftpSim?: Map<string, SimNode> };
167	const simStore: Map<string, SimNode> = globalForSim.__nxeonSftpSim ?? new Map();
168	globalForSim.__nxeonSftpSim = simStore;
169	
170	function seedSim(): SimNode {
171	  const now = Date.now();
172	  const file = (content: string, mode = 0o644): SimNode => ({
173	    type: "file",
174	    mtime: now,
175	    mode,
176	    content,
177	  });
178	  const dir = (children: Record<string, SimNode>, mode = 0o755): SimNode => ({
179	    type: "dir",
180	    mtime: now,
181	    mode,
182	    children,
183	  });
184	  return dir({
185	    root: dir({
186	      "readme.txt": file(
187	        "Welcome to your VPS (sandbox).\n\nThis is a simulated filesystem shown on the staging\nenvironment — no real SSH connection is made.\n"
188	      ),
189	      ".bashrc": file("# ~/.bashrc\nexport PATH=$PATH:/usr/local/bin\n"),
190	      projects: dir({
191	        "app.js": file("console.log('hello from your server');\n"),
192	        "notes.md": file("# Notes\n\n- Edit me from the file manager.\n"),
193	      }),
194	    }),
195	    etc: dir({
196	      "hostname": file("nxeon-vps\n"),
197	      "os-release": file('PRETTY_NAME="Ubuntu 24.04 LTS"\n', 0o644),
198	    }),
199	    var: dir({
200	      log: dir({
201	        "syslog": file("Jan  1 00:00:00 nxeon-vps systemd[1]: Started sandbox.\n"),
202	      }),
203	      www: dir({
204	        html: dir({
205	          "index.html": file("<!doctype html><h1>It works</h1>\n"),
206	        }),
207	      }),
208	    }),
209	    tmp: dir({}),
210	  });
211	}
212	
213	function simRoot(serverId: string): SimNode {
214	  let node = simStore.get(serverId);
215	  if (!node) {
216	    node = seedSim();
217	    simStore.set(serverId, node);
218	  }
219	  return node;
220	}
221	
222	/** Convert an rwx rights triad ("rwx","r-x","r--") into an octal mode integer. */
223	function rightsToMode(rights: { user: string; group: string; other: string }): number | null {
224	  if (!rights) return null;
225	  const bits = (s: string): number =>
226	    (s.includes("r") ? 4 : 0) + (s.includes("w") ? 2 : 0) + (s.includes("x") ? 1 : 0);
227	  return (bits(rights.user) << 6) | (bits(rights.group) << 3) | bits(rights.other);
228	}
229	
230	function splitPath(p: string): string[] {
231	  return p.split("/").filter((s) => s.length > 0);
232	}
233	
234	function simResolve(serverId: string, p: string): SimNode | null {
235	  let node = simRoot(serverId);
236	  for (const part of splitPath(p)) {
237	    if (node.type !== "dir") return null;
238	    const next = node.children[part];
239	    if (!next) return null;
240	    node = next;
241	  }
242	  return node;
243	}
244	
245	function simParent(serverId: string, p: string): { parent: SimDir; name: string } | null {
246	  const parts = splitPath(p);
247	  if (parts.length === 0) return null;
248	  const name = parts[parts.length - 1];
249	  const parentPath = "/" + parts.slice(0, -1).join("/");
250	  const parent = simResolve(serverId, parentPath);
251	  if (!parent || parent.type !== "dir") return null;
252	  return { parent, name };
253	}
