320	/**
321	 * Read a text file, capped at `maxBytes`. Throws if the target is larger than
322	 * the cap so we never buffer an unbounded file into memory / the editor.
323	 */
324	export async function readFileText(
325	  server: SftpServer,
326	  path: string,
327	  maxBytes: number
328	): Promise<string> {
329	  if (SANDBOX) {
330	    const node = simResolve(server.id, path);
331	    if (!node) throw new Error("No such file.");
332	    if (node.type !== "file") throw new Error("Not a file.");
333	    if (Buffer.byteLength(node.content) > maxBytes) {
334	      throw new Error("File is too large to edit in the browser.");
335	    }
336	    return node.content;
337	  }
338	
339	  return withSftp(server, async (client) => {
340	    const s = await client.stat(path);
341	    if (s.isDirectory) throw new Error("Not a file.");
342	    if (s.size > maxBytes) throw new Error("File is too large to edit in the browser.");
343	    const buf = (await client.get(path)) as Buffer;
344	    return buf.toString("utf8");
345	  });
346	}
347	
348	export async function writeFileText(
349	  server: SftpServer,
350	  path: string,
351	  content: string
352	): Promise<void> {
353	  if (SANDBOX) {
354	    const loc = simParent(server.id, path);
355	    if (!loc) throw new Error("Invalid path.");
356	    const existing = loc.parent.children[loc.name];
357	    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
358	    loc.parent.children[loc.name] = {
359	      type: "file",
360	      mtime: Date.now(),
361	      mode: existing?.type === "file" ? existing.mode : 0o644,
362	      content,
363	    };
364	    return;
365	  }
366	
367	  await withSftp(server, async (client) => {
368	    await client.put(Buffer.from(content, "utf8"), path);
369	  });
370	}
371	
372	export async function mkdirPath(server: SftpServer, path: string): Promise<void> {
373	  if (SANDBOX) {
374	    const loc = simParent(server.id, path);
375	    if (!loc) throw new Error("Invalid path.");
376	    if (loc.parent.children[loc.name]) throw new Error("A file or folder with that name already exists.");
377	    loc.parent.children[loc.name] = { type: "dir", mtime: Date.now(), mode: 0o755, children: {} };
378	    return;
379	  }
380	
381	  await withSftp(server, async (client) => {
382	    await client.mkdir(path, false);
383	  });
384	}
385	
386	export async function renamePath(
387	  server: SftpServer,
388	  from: string,
389	  to: string
390	): Promise<void> {
391	  if (SANDBOX) {
392	    const src = simResolve(server.id, from);
393	    if (!src) throw new Error("No such file or directory.");
394	    const dst = simParent(server.id, to);
395	    if (!dst) throw new Error("Invalid destination.");
396	    if (dst.parent.children[dst.name]) {
397	      throw new Error("A file or folder with that name already exists.");
398	    }
399	    const srcLoc = simParent(server.id, from);
400	    if (!srcLoc) throw new Error("Cannot rename the root.");
401	    delete srcLoc.parent.children[srcLoc.name];
402	    dst.parent.children[dst.name] = { ...src, mtime: Date.now() };
403	    return;
404	  }
405	
406	  await withSftp(server, async (client) => {
407	    await client.rename(from, to);
408	  });
409	}
410	
411	/** Remove a file, or recursively remove a directory. */
412	export async function removePath(server: SftpServer, path: string): Promise<void> {
413	  if (SANDBOX) {
414	    const loc = simParent(server.id, path);
415	    if (!loc) throw new Error("Cannot remove the root.");
416	    if (!loc.parent.children[loc.name]) throw new Error("No such file or directory.");
417	    delete loc.parent.children[loc.name];
418	    return;
419	  }
420	
421	  await withSftp(server, async (client) => {
422	    const s = await client.stat(path);
423	    if (s.isDirectory) {
424	      await client.rmdir(path, true); // recursive
425	    } else {
426	      await client.delete(path);
427	    }
428	  });
429	}
430	
431	export async function chmodPath(server: SftpServer, path: string, mode: number): Promise<void> {
432	  if (SANDBOX) {
433	    const node = simResolve(server.id, path);
434	    if (!node) throw new Error("No such file or directory.");
435	    node.mode = mode & 0o777;
436	    return;
437	  }
438	
439	  await withSftp(server, async (client) => {
440	    await client.chmod(path, mode & 0o777);
441	  });
442	}
