31	/** Reject if another job is already queued/running on this server. */
32	async function ensureIdle(serverId: string): Promise<{ error?: string }> {
33	  const pending = await db.job.count({
34	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
35	  });
36	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
37	  return {};
