42	/**
43	 * Toggle `Server.autoUpdate` for a game server. Read-only for non-game images
44	 * (returns an error). The periodic worker sweep uses this flag.
45	 */
46	export async function toggleAutoUpdate(
47	  serverId: string,
48	  enabled: boolean
49	): Promise<{ error?: string; autoUpdate?: boolean }> {
50	  const { user, server } = await ownedServer(serverId);
51	  if (!isGameServer(server)) return { error: "Auto-update is only available for game servers." };
52	
53	  await db.server.update({ where: { id: server.id }, data: { autoUpdate: enabled } });
54	  await db.auditLog.create({
