1	import { NextRequest, NextResponse } from "next/server";
2	import { createHash, randomUUID } from "node:crypto";
3	import { EncryptJWT } from "jose";
4	import { db } from "@/lib/db";
5	import { currentUser } from "@/lib/auth";
6	import { checkRateLimit } from "@/lib/rate-limit";
7	import { pve, node as primaryNode } from "@/lib/proxmox";
8	
9	export const dynamic = "force-dynamic";
10	
11	/**
12	 * In-browser VNC console — ticket issuer.
13	 *
14	 * GET /api/console/[serverId]
15	 *
16	 * Flow:
17	 *  1. Authenticate the caller (owner or admin).
18	 *  2. Ask Proxmox for a websocket VNC proxy ticket for the server's VM
19	 *     (POST .../vncproxy?websocket=1). This returns a short-lived VNC ticket +
20	 *     an ephemeral port on the Proxmox node.
21	 *  3. Package the connection target — Proxmox API base, node, vmid, port, the
22	 *     VNC ticket, and the API token needed to authenticate the websocket
23	 *     upgrade — into an ENCRYPTED (JWE / A256GCM) token, valid 60s, with a
24	 *     unique jti so the relay can enforce single use.
25	 *  4. Return only { wsPath, ticketId } to the browser. The browser NEVER sees
26	 *     the Proxmox API token or the raw VNC ticket — those live inside the JWE,
27	 *     which only the relay (sharing AUTH_SECRET) can decrypt.
28	 *
29	 * The relay (scripts/console-proxy.mjs) receives sid=<JWE> on the browser
30	 * websocket, decrypts it, opens a TLS websocket to Proxmox with the real
31	 * credentials, and pipes bytes both ways.
32	 */
33	
34	// 256-bit symmetric key for JWE, derived from the app's AUTH_SECRET.
35	// The relay derives the identical key the same way — no extra shared secret.
36	function consoleKey(): Uint8Array {
37	  const secret = process.env.AUTH_SECRET;
38	  if (!secret) throw new Error("AUTH_SECRET is not set");
39	  return new Uint8Array(createHash("sha256").update(`nxeon-console:${secret}`).digest());
40	}
41	
42	export async function GET(
43	  _req: NextRequest,
44	  { params }: { params: Promise<{ serverId: string }> }
45	) {
46	  const { serverId } = await params;
47	
48	  const user = await currentUser();
49	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
50	
51	  // Throttle ticket minting per user (falling back to IP) BEFORE we ask
52	  // Proxmox for a vncproxy ticket — each grant spawns an ephemeral vncproxy
53	  // process, so an unthrottled loop could orphan thousands of them.
54	  const xff = _req.headers.get("x-forwarded-for") ?? "";
55	  const ip = xff.split(",")[0]?.trim() || "unknown";
56	  const rl = checkRateLimit(`console:${user.id || ip}`, { max: 10, windowMs: 60_000 });
57	  if (!rl.ok) {
58	    return NextResponse.json(
59	      { error: "too many console requests — slow down", retryAfterSec: rl.retryAfterSec },
60	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
61	    );
62	  }
63	
64	  const server = await db.server.findUnique({
65	    where: { id: serverId },
66	    include: { node: true },
67	  });
68	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
69	    return NextResponse.json({ error: "not found" }, { status: 404 });
70	  }
71	  if (!server.vmid) {
72	    return NextResponse.json({ error: "no VM provisioned" }, { status: 409 });
73	  }
74	  if (server.status !== "RUNNING") {
75	    return NextResponse.json(
76	      { error: "server must be running to open the console" },
77	      { status: 409 }
78	    );
79	  }
80	
81	  // Resolve which Proxmox node + credentials to use. Multi-node servers carry a
82	  // Node row; otherwise fall back to the primary node from the environment.
83	  const apiBase = server.node?.apiUrl ?? process.env.PROXMOX_API_URL ?? "https://127.0.0.1:8006";
84	  const pveNode = server.node?.pveNode ?? primaryNode;
85	  const tokenId = server.node?.tokenId ?? process.env.PROXMOX_TOKEN_ID ?? "";
86	  const tokenSecret = server.node?.tokenSecret ?? process.env.PROXMOX_TOKEN_SECRET ?? "";
87	
88	  if (!pveNode || !tokenId || !tokenSecret) {
89	    return NextResponse.json({ error: "console not configured" }, { status: 500 });
90	  }
91	
92	  // Request a websocket VNC proxy ticket from Proxmox.
93	  let vnc: { ticket: string; port: string | number };
94	  try {
95	    // Use the node-scoped client for non-primary nodes so the ticket is valid
96	    // for the right host; the primary node uses the shared `pve` client.
97	    if (server.node) {
98	      const { pveFor } = await import("@/lib/proxmox");
99	      const client = pveFor({
100	        apiUrl: server.node.apiUrl,
101	        pveNode: server.node.pveNode,
102	        tokenId: server.node.tokenId,
103	        tokenSecret: server.node.tokenSecret,
104	      });
105	      vnc = await client.post(`/nodes/${pveNode}/qemu/${server.vmid}/vncproxy`, {
106	        websocket: 1,
107	      });
108	    } else {
109	      vnc = await pve.post(`/nodes/${pveNode}/qemu/${server.vmid}/vncproxy`, {
110	        websocket: 1,
111	      });
112	    }
113	  } catch {
114	    return NextResponse.json(
115	      { error: "hypervisor did not grant a console ticket — try again shortly" },
116	      { status: 502 }
117	    );
118	  }
119	
120	  if (!vnc?.ticket || vnc.port === undefined) {
121	    return NextResponse.json({ error: "invalid console ticket from hypervisor" }, { status: 502 });
122	  }
123	
124	  const ticketId = randomUUID();
125	
126	  // Encrypt the full connection target. Only the relay can read this.
127	  const sid = await new EncryptJWT({
128	    apiBase,
129	    node: pveNode,
130	    vmid: server.vmid,
131	    port: Number(vnc.port),
132	    vncticket: vnc.ticket,
133	    tokenId,
134	    tokenSecret,
135	  })
136	    .setProtectedHeader({ alg: "dir", enc: "A256GCM" })
137	    .setJti(ticketId)
138	    .setIssuedAt()
139	    .setExpirationTime("60s")
140	    .encrypt(consoleKey());
141	
142	  // Public websocket URL of the relay. In production behind HTTPS, set
143	  // CONSOLE_PUBLIC_WS_URL to a wss:// endpoint (e.g. proxied by nginx) so the
144	  // browser isn't blocked by mixed-content. Otherwise we hand out a bare
145	  // ws://PUBLIC_IP:PORT/console URL for the standalone relay.
146	  const base =
147	    process.env.CONSOLE_PUBLIC_WS_URL?.replace(/\/+$/, "") ??
148	    `ws://${process.env.PUBLIC_IP ?? "127.0.0.1"}:${process.env.CONSOLE_PROXY_PORT ?? "8899"}/console`;
149	
150	  const wsPath = `${base}?sid=${encodeURIComponent(sid)}`;
151	
152	  return NextResponse.json({ wsPath, ticketId });
153	}
