109	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
110	
111	  const rl = checkRateLimit(`files:upload:${user.id}`, { max: 30, windowMs: 60_000 });
112	  if (!rl.ok) {
113	    return NextResponse.json(
114	      { error: "too many uploads — slow down", retryAfterSec: rl.retryAfterSec },
115	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
116	    );
117	  }
118	
119	  const server = await ownedServer(serverId, user.id, user.role === "ADMIN");
120	  if (!server) return NextResponse.json({ error: "not found" }, { status: 404 });
121	
122	  let dir: string;
123	  try {
124	    dir = normalizePath(req.nextUrl.searchParams.get("path") ?? "");
125	  } catch (err) {
126	    return NextResponse.json(
127	      { error: err instanceof Error ? err.message : "invalid path" },
128	      { status: 400 }
129	    );
130	  }
131	
132	  let form: FormData;
133	  try {
134	    form = await req.formData();
135	  } catch {
136	    return NextResponse.json({ error: "expected a multipart upload" }, { status: 400 });
137	  }
138	
139	  const file = form.get("file");
140	  if (!(file instanceof File)) {
141	    return NextResponse.json({ error: "no file provided" }, { status: 400 });
142	  }
143	  if (file.size > MAX_UPLOAD_BYTES) {
144	    return NextResponse.json(
145	      { error: `file exceeds the ${MAX_UPLOAD_BYTES / (1024 * 1024)} MB upload limit` },
146	      { status: 413 }
147	    );
148	  }
149	
150	  let target: string;
151	  try {
152	    const name = validateName((file.name || "upload").trim());
153	    target = joinPath(dir, name);
154	  } catch (err) {
155	    return NextResponse.json(
156	      { error: err instanceof Error ? err.message : "invalid filename" },
157	      { status: 400 }
158	    );
159	  }
160	
161	  try {
162	    const data = Buffer.from(await file.arrayBuffer());
163	    // Re-check the actual byte length in case the reported size was understated.
164	    if (data.length > MAX_UPLOAD_BYTES) {
165	      return NextResponse.json({ error: "file too large" }, { status: 413 });
166	    }
167	    await writeFileBuffer(server, target, data);
168	  } catch (err) {
169	    const msg = err instanceof Error ? err.message : "upload failed";
170	    const status = /Invalid|directory/i.test(msg) ? 400 : 502;
171	    return NextResponse.json({ error: msg }, { status });
172	  }
173	
174	  return NextResponse.json({ ok: true, path: target });
175	}
