/**
 * Short-lived, encrypted authorization tokens for the in-portal web terminal.
 *
 * The browser never opens the terminal websocket with its session cookie —
 * instead the app mints a 60-second, single-purpose token (this module) that
 * encodes exactly {userId, serverId}. The standalone PTY backend
 * (terminal-server/index.ts) verifies that token before it will SSH anywhere.
 *
 * The token is a JWE (encrypted, A256GCM) — mirroring the VNC console ticket in
 * app/api/console/[serverId]/route.ts — so its contents are opaque to the
 * browser and cannot be tampered with. The symmetric key is DERIVED from the
 * app's AUTH_SECRET the same way the console does, with a terminal-specific
 * salt, so the web app and the terminal backend agree on the key with no extra
 * shared secret to configure.
 *
 * Plain server-side module (no "use server"): importable by both the Next route
 * handler and the tsx-run terminal backend.
 */
import { createHash } from "node:crypto";
import { EncryptJWT, jwtDecrypt } from "jose";

/** Lifetime of a minted terminal token. It only needs to survive the round-trip
 * from `POST /api/terminal/token` to the websocket upgrade. */
export const TERMINAL_TOKEN_TTL_SECONDS = 60;

/** What every terminal token carries. Nothing sensitive — just who + which VM. */
export type TerminalTokenClaims = {
  userId: string;
  serverId: string;
};

/**
 * 256-bit symmetric key for the terminal JWE, derived from AUTH_SECRET. The
 * terminal backend derives the identical key the same way, so no separate
 * secret needs distributing. Distinct salt from the console key so a console
 * ticket can never be replayed as a terminal token (or vice-versa).
 */
function terminalKey(): Uint8Array {
  const secret = process.env.AUTH_SECRET;
  if (!secret) throw new Error("AUTH_SECRET is not set");
  return new Uint8Array(createHash("sha256").update(`nxeon-terminal:${secret}`).digest());
}

/** Mint an encrypted, 60-second terminal token for {userId, serverId}. */
export async function signTerminalToken(claims: TerminalTokenClaims): Promise<string> {
  return new EncryptJWT({ userId: claims.userId, serverId: claims.serverId })
    .setProtectedHeader({ alg: "dir", enc: "A256GCM" })
    .setIssuedAt()
    .setExpirationTime(`${TERMINAL_TOKEN_TTL_SECONDS}s`)
    .encrypt(terminalKey());
}

/**
 * Verify + decrypt a terminal token. Returns the claims, or throws if the token
 * is missing, malformed, tampered with, or expired (jwtDecrypt enforces `exp`).
 */
export async function verifyTerminalToken(token: string): Promise<TerminalTokenClaims> {
  const { payload } = await jwtDecrypt(token, terminalKey());
  const userId = payload.userId;
  const serverId = payload.serverId;
  if (typeof userId !== "string" || typeof serverId !== "string" || !userId || !serverId) {
    throw new Error("terminal token missing userId/serverId");
  }
  return { userId, serverId };
}

import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { signTerminalToken } from "@/lib/terminal-token";

/**
 * Web-terminal authorization ticket issuer.
 *
 *   POST /api/terminal/token   { serverId }
 *
 * Flow:
 *  1. Authenticate the caller (reuses lib/auth `requireUser`).
 *  2. Verify the caller OWNS the target server (userId match — or an admin) and
 *     that it is RUNNING. This is the ONLY place the session cookie is checked;
 *     the websocket itself is authorized purely by the token minted here.
 *  3. Mint a 60-second encrypted token encoding { userId, serverId } and return
 *     it. The browser hands this token to the terminal websocket, which
 *     re-verifies it and re-checks ownership before SSHing to the VM.
 *
 * The token is short-lived and single-purpose: it authorizes opening ONE shell
 * on ONE server for the user it names. It carries no credentials — the VM's
 * root password never leaves the server side.
 */
export const dynamic = "force-dynamic";

export async function POST(req: NextRequest) {
  let user;
  try {
    user = await requireUser();
  } catch {
    return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  }

  // Throttle minting per user so a stolen session can't spin up shells in a loop.
  const rl = checkRateLimit(`terminal:token:${user.id}`, { max: 20, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "too many terminal requests — slow down", retryAfterSec: rl.retryAfterSec },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  let serverId: unknown;
  try {
    const body = await req.json();
    serverId = body?.serverId;
  } catch {
    return NextResponse.json({ error: "expected a JSON body" }, { status: 400 });
  }
  if (typeof serverId !== "string" || !serverId) {
    return NextResponse.json({ error: "serverId is required" }, { status: 400 });
  }

  // Ownership check — same pattern as lib/actions-server-ops.ts / app/api/files:
  // the server must exist and belong to the caller (admins may open any).
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: { id: true, userId: true, status: true },
  });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }
  if (server.status !== "RUNNING") {
    return NextResponse.json(
      { error: "server must be running to open a terminal" },
      { status: 409 }
    );
  }

  const token = await signTerminalToken({ userId: user.id, serverId: server.id });
  return NextResponse.json({ token });
}

/**
 * Nxeon in-portal web terminal — standalone PTY websocket backend.
 *
 * A tiny long-running Node process (run with tsx, NOT bundled by Next) that
 * bridges a browser xterm.js websocket to a real SSH shell on a customer VM:
 *
 *   browser  ──ws──▶  terminal-server  ──ssh2──▶  customer VM (root shell / PTY)
 *   (xterm.js)        (holds nothing)             (the actual shell)
 *
 * SECURITY MODEL
 *  - The websocket is authorized ONLY by a short-lived encrypted token minted by
 *    app/api/terminal/token (POST, session-checked, ownership-checked). This
 *    process re-verifies that token, then RE-LOADS the server and RE-CHECKS
 *    ownership (userId match) and status (RUNNING) against the database before
 *    it opens any SSH connection. A token names one user + one server and is
 *    valid for 60 seconds.
 *  - The VM's root password is fetched here (lib/sftp serverRootPassword, which
 *    decrypts rootPasswordEnc) and used to authenticate the SSH connection. It
 *    NEVER crosses the websocket and is NEVER logged.
 *  - Listens on 127.0.0.1 only — it is meant to sit behind nginx, which proxies
 *    /terminal-ws (with WebSocket upgrade headers) to this port.
 *
 * LIMITS ENFORCED PER SESSION
 *  - 15s to authenticate the token + establish the SSH shell, else the socket is
 *    closed.
 *  - 10 min idle (no bytes either direction) → closed.
 *  - 60 min hard cap on total session duration → closed.
 *
 * SANDBOX (NXEON_SANDBOX=1): no SSH is ever opened. After the same token +
 * ownership checks, a friendly simulated shell is piped (banner + echo) so the
 * staging environment works end to end without real VMs.
 *
 * ENV (read from the same /opt/nxeon/.env as the web app, via systemd
 * EnvironmentFile; a best-effort .env loader below covers manual runs):
 *   AUTH_SECRET              shared secret — must match the web app (required)
 *   DATABASE_URL             Prisma connection (required)
 *   PUBLIC_IP                for NAT servers' host resolution (lib/sftp)
 *   NXEON_TERMINAL_WS_PORT   listen port (default 8901)
 *   NXEON_TERMINAL_WS_HOST   listen address (default 127.0.0.1)
 *
 * Run: npx tsx terminal-server/index.ts
 */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import type { IncomingMessage } from "node:http";

// --- Best-effort .env loader (systemd already provides these; this only fills
// gaps for manual `npx tsx` runs, and NEVER overrides an existing env var). ---
function loadDotEnv(): void {
  if (process.env.AUTH_SECRET && process.env.DATABASE_URL) return;
  try {
    const text = readFileSync(resolve(process.cwd(), ".env"), "utf8");
    for (const raw of text.split("\n")) {
      const line = raw.trim();
      if (!line || line.startsWith("#")) continue;
      const eq = line.indexOf("=");
      if (eq === -1) continue;
      const key = line.slice(0, eq).trim();
      if (key in process.env) continue;
      let val = line.slice(eq + 1).trim();
      if (
        (val.startsWith('"') && val.endsWith('"')) ||
        (val.startsWith("'") && val.endsWith("'"))
      ) {
        val = val.slice(1, -1);
      }
      process.env[key] = val;
    }
  } catch {
    /* no .env file — rely on the real environment */
  }
}
loadDotEnv();

import { WebSocketServer, WebSocket } from "ws";
import { Client as SshClient } from "ssh2";
import { db } from "../lib/db";
import { connectionTarget, serverRootPassword } from "../lib/sftp";
import { verifyTerminalToken } from "../lib/terminal-token";
import { SANDBOX } from "../lib/sandbox";

const PORT = Number(process.env.NXEON_TERMINAL_WS_PORT ?? 8901);
const HOST = process.env.NXEON_TERMINAL_WS_HOST ?? "127.0.0.1";

const AUTH_CONNECT_TIMEOUT_MS = 15_000;
const IDLE_TIMEOUT_MS = 10 * 60_000; // 10 minutes with no traffic either way
const MAX_SESSION_MS = 60 * 60_000; // 60 minutes hard cap

/** Client → server control frames. Server → client is always raw shell output. */
type ClientMsg =
  | { type: "data"; data: string }
  | { type: "resize"; cols: number; rows: number };

/** Sanitize dimensions coming from the browser into a sane PTY window. */
function clampDim(n: unknown, fallback: number): number {
  const v = Math.trunc(Number(n));
  if (!Number.isFinite(v) || v <= 0) return fallback;
  return Math.min(Math.max(v, 1), 1000);
}

if (!process.env.AUTH_SECRET) {
  console.error("[terminal-server] FATAL: AUTH_SECRET not set");
  process.exit(1);
}

const wss = new WebSocketServer({ host: HOST, port: PORT });

wss.on("listening", () => {
  console.log(
    `[terminal-server] listening on ws://${HOST}:${PORT}${SANDBOX ? " (SANDBOX)" : ""}`
  );
});

wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
  void handleConnection(ws, req);
});

async function handleConnection(ws: WebSocket, req: IncomingMessage): Promise<void> {
  let closed = false;
  let idleTimer: NodeJS.Timeout | null = null;
  let authTimer: NodeJS.Timeout | null = null;
  let maxTimer: NodeJS.Timeout | null = null;
  let ssh: SshClient | null = null;

  /** Close everything exactly once; optionally send a final line to the client. */
  function shutdown(reason: string, notify?: string): void {
    if (closed) return;
    closed = true;
    if (idleTimer) clearInterval(idleTimer);
    if (authTimer) clearTimeout(authTimer);
    if (maxTimer) clearTimeout(maxTimer);
    if (notify && ws.readyState === WebSocket.OPEN) {
      try {
        ws.send(`\r\n\x1b[33m${notify}\x1b[0m\r\n`);
      } catch {
        /* ignore */
      }
    }
    try {
      ssh?.end();
    } catch {
      /* ignore */
    }
    try {
      if (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING) {
        ws.close(1000, reason.slice(0, 120));
      }
    } catch {
      /* ignore */
    }
  }

  // --- Idle + max-duration guards -------------------------------------------
  let lastActivity = Date.now();
  const bump = () => {
    lastActivity = Date.now();
  };
  idleTimer = setInterval(() => {
    if (Date.now() - lastActivity > IDLE_TIMEOUT_MS) {
      shutdown("idle timeout", "Session closed after 10 minutes of inactivity.");
    }
  }, 15_000);
  idleTimer.unref?.();
  maxTimer = setTimeout(() => {
    shutdown("max duration", "Session ended — 60 minute limit reached.");
  }, MAX_SESSION_MS);
  maxTimer.unref?.();

  // Must authenticate + establish a shell within the auth/connect window.
  authTimer = setTimeout(() => {
    shutdown("auth/connect timeout", "Timed out establishing the terminal session.");
  }, AUTH_CONNECT_TIMEOUT_MS);
  authTimer.unref?.();

  ws.on("error", () => shutdown("ws error"));
  ws.on("close", () => shutdown("ws closed"));

  // --- Verify the token from the query string --------------------------------
  let claims: { userId: string; serverId: string };
  try {
    const url = new URL(req.url ?? "/", "http://localhost");
    const token = url.searchParams.get("token");
    if (!token) {
      shutdown("no token", "No authorization token supplied.");
      return;
    }
    claims = await verifyTerminalToken(token);
  } catch {
    shutdown("bad token", "Authorization token is invalid or expired.");
    return;
  }
  if (closed) return;

  // --- Re-load the server and RE-CHECK ownership + RUNNING --------------------
  const server = await db.server.findUnique({
    where: { id: claims.serverId },
    select: {
      id: true,
      userId: true,
      status: true,
      rootPassword: true,
      rootPasswordEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
    },
  });
  if (closed) return;
  if (!server || server.userId !== claims.userId) {
    shutdown("ownership", "You do not have access to this server.");
    return;
  }
  if (server.status !== "RUNNING") {
    shutdown("not running", "Server is not running.");
    return;
  }

  // --- SANDBOX: simulated shell, no SSH --------------------------------------
  if (SANDBOX) {
    if (authTimer) {
      clearTimeout(authTimer);
      authTimer = null;
    }
    startSandboxShell(ws, bump, shutdown);
    return;
  }

  // --- Resolve connection target + credentials -------------------------------
  const target = connectionTarget(server);
  if (!target) {
    shutdown("unreachable", "Server is not reachable yet — connection details are pending.");
    return;
  }
  const password = serverRootPassword(server);
  if (!password) {
    shutdown("no password", "Server has no root password set.");
    return;
  }

  // --- Open the SSH connection + request a PTY shell -------------------------
  ssh = new SshClient();

  ssh.on("ready", () => {
    if (closed) {
      ssh?.end();
      return;
    }
    ssh!.shell({ term: "xterm-256color", cols: 80, rows: 24 }, (err, stream) => {
      if (err || closed) {
        shutdown("shell error", "Could not open a shell on the server.");
        return;
      }
      // Shell is live — clear the auth/connect deadline.
      if (authTimer) {
        clearTimeout(authTimer);
        authTimer = null;
      }
      bump();

      // Server → client: raw shell output.
      stream.on("data", (chunk: Buffer) => {
        bump();
        if (ws.readyState === WebSocket.OPEN) ws.send(chunk);
      });
      stream.stderr?.on("data", (chunk: Buffer) => {
        bump();
        if (ws.readyState === WebSocket.OPEN) ws.send(chunk);
      });
      stream.on("close", () => shutdown("shell closed"));

      // Client → server: JSON control frames (keystrokes + resize).
      ws.on("message", (raw: Buffer, isBinary: boolean) => {
        bump();
        const msg = parseClientMsg(raw, isBinary);
        if (!msg) return;
        if (msg.type === "data") {
          stream.write(msg.data);
        } else if (msg.type === "resize") {
          try {
            stream.setWindow(msg.rows, msg.cols, 0, 0);
          } catch {
            /* ignore resize failures */
          }
        }
      });
    });
  });

  ssh.on("error", () => {
    // Never surface SSH internals (or anything password-adjacent) to the client.
    shutdown("ssh error", "Could not connect to the server. Please try again.");
  });
  ssh.on("close", () => shutdown("ssh closed"));

  try {
    ssh.connect({
      host: target.host,
      port: target.port,
      username: "root",
      password,
      readyTimeout: AUTH_CONNECT_TIMEOUT_MS,
      keepaliveInterval: 20_000,
    });
  } catch {
    shutdown("connect threw", "Could not connect to the server.");
  }
}

/** Parse a client→server frame. Returns null for anything unrecognized. */
function parseClientMsg(raw: Buffer, isBinary: boolean): ClientMsg | null {
  if (isBinary) return null;
  let obj: unknown;
  try {
    obj = JSON.parse(raw.toString("utf8"));
  } catch {
    return null;
  }
  if (!obj || typeof obj !== "object") return null;
  const m = obj as Record<string, unknown>;
  if (m.type === "data" && typeof m.data === "string") {
    return { type: "data", data: m.data };
  }
  if (m.type === "resize") {
    return { type: "resize", cols: clampDim(m.cols, 80), rows: clampDim(m.rows, 24) };
  }
  return null;
}

/**
 * Sandbox shell: a friendly simulated terminal. No SSH — just a banner and a
 * local echo of what the user types, so the whole UX works on staging.
 */
function startSandboxShell(
  ws: WebSocket,
  bump: () => void,
  shutdown: (reason: string, notify?: string) => void
): void {
  const nl = "\r\n";
  const prompt = "\x1b[32mnxeon-sandbox\x1b[0m:\x1b[34m~\x1b[0m# ";
  const banner =
    `\x1b[36mNxeon sandbox terminal\x1b[0m${nl}` +
    `This is a simulated shell on the staging environment — no real SSH` +
    ` connection is made.${nl}` +
    `Type anything and it will be echoed back. On production this is a real` +
    ` root shell where you can run \x1b[1mclaude\x1b[0m.${nl}${nl}`;

  if (ws.readyState === WebSocket.OPEN) ws.send(banner + prompt);

  let line = "";
  ws.on("message", (raw: Buffer, isBinary: boolean) => {
    bump();
    const msg = parseClientMsg(raw, isBinary);
    if (!msg || msg.type !== "data") return; // ignore resize in the sim
    for (const ch of msg.data) {
      if (ch === "\r" || ch === "\n") {
        let out = nl;
        if (line.trim()) out += `you typed: ${line}${nl}`;
        line = "";
        if (ws.readyState === WebSocket.OPEN) ws.send(out + prompt);
      } else if (ch === "\x7f" || ch === "\b") {
        if (line.length > 0) {
          line = line.slice(0, -1);
          if (ws.readyState === WebSocket.OPEN) ws.send("\b \b");
        }
      } else if (ch >= " ") {
        line += ch;
        if (ws.readyState === WebSocket.OPEN) ws.send(ch);
      }
    }
  });

  // Keep the same guarantee that the socket eventually closes.
  void shutdown;
}

process.on("SIGTERM", () => wss.close(() => process.exit(0)));
process.on("SIGINT", () => wss.close(() => process.exit(0)));

# Nxeon web terminal — nginx location snippet.
#
# Add this INSIDE the existing `server { ... }` block for the portal vhost
# (the same HTTPS server that proxies the Next.js app). It upgrades the
# browser's WebSocket to the standalone terminal backend listening on
# 127.0.0.1:8901 (NXEON_TERMINAL_WS_PORT).
#
# The browser connects to:  wss://<portal-host>/terminal-ws?token=<...>
# The `?token=` query string is forwarded automatically by proxy_pass.
#
# Requires the standard connection-upgrade map (add once, at the http{} level,
# if it is not already present for the VNC console relay):
#
#   map $http_upgrade $connection_upgrade {
#       default upgrade;
#       ''      close;
#   }

location /terminal-ws {
    proxy_pass http://127.0.0.1:8901;
    proxy_http_version 1.1;

    # WebSocket upgrade headers.
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection $connection_upgrade;

    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;

    # A terminal session is long-lived and mostly idle between keystrokes — keep
    # the upstream connection open well past nginx's default 60s read timeout.
    # (The backend enforces its own 10-min idle / 60-min max limits.)
    proxy_read_timeout 3600s;
    proxy_send_timeout 3600s;

    # Terminal output must not be buffered — flush bytes to the browser at once.
    proxy_buffering off;
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import type { Terminal as XTerm } from "@xterm/xterm";
import type { FitAddon as XFitAddon } from "@xterm/addon-fit";
import "@xterm/xterm/css/xterm.css";

/**
 * In-portal web terminal — a slide-in panel with an xterm.js terminal wired to
 * a real root shell on one of the customer's running servers.
 *
 * Security: the websocket is authorized by a short-lived token minted by
 * POST /api/terminal/token (which checks the session + ownership). This
 * component never sees any server credential — only the opaque token.
 *
 * Wire protocol (matches terminal-server/index.ts):
 *   client → server : JSON  {type:"data",data} | {type:"resize",cols,rows}
 *   server → client : raw shell output (text or binary) → written to xterm
 */

export type TerminalServer = { id: string; hostname: string };

type Status = "idle" | "connecting" | "connected" | "closed" | "error";

export function WebTerminal({
  servers,
  onClose,
}: {
  servers: TerminalServer[];
  onClose: () => void;
}) {
  const [mounted, setMounted] = useState(false);
  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
  const [status, setStatus] = useState<Status>("idle");
  const [error, setError] = useState<string | null>(null);

  const hostRef = useRef<HTMLDivElement | null>(null);
  const termRef = useRef<XTerm | null>(null);
  const fitRef = useRef<XFitAddon | null>(null);
  const wsRef = useRef<WebSocket | null>(null);
  const roRef = useRef<ResizeObserver | null>(null);
  const disposedRef = useRef(false);

  useEffect(() => {
    setMounted(true);
    return () => {
      disposedRef.current = true;
    };
  }, []);

  const selected = useMemo(
    () => servers.find((s) => s.id === serverId) ?? null,
    [servers, serverId]
  );

  /** Tear down the live websocket + terminal (idempotent). */
  function teardown() {
    try {
      roRef.current?.disconnect();
    } catch {
      /* ignore */
    }
    roRef.current = null;
    try {
      wsRef.current?.close();
    } catch {
      /* ignore */
    }
    wsRef.current = null;
    try {
      termRef.current?.dispose();
    } catch {
      /* ignore */
    }
    termRef.current = null;
    fitRef.current = null;
  }

  useEffect(() => {
    // Clean up whenever the panel unmounts.
    return () => teardown();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function sendResize() {
    const term = termRef.current;
    const fit = fitRef.current;
    const ws = wsRef.current;
    if (!term || !fit) return;
    try {
      fit.fit();
    } catch {
      /* ignore */
    }
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify({ type: "resize", cols: term.cols, rows: term.rows }));
    }
  }

  async function connect() {
    if (!serverId) return;
    setError(null);
    setStatus("connecting");
    teardown();

    // 1. Mint a short-lived token (session + ownership checked server-side).
    let token: string;
    try {
      const res = await fetch("/api/terminal/token", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ serverId }),
      });
      const body = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(body?.error || "Could not authorize the terminal.");
      token = body.token;
      if (!token) throw new Error("No terminal token was issued.");
    } catch (e) {
      setStatus("error");
      setError(e instanceof Error ? e.message : "Could not authorize the terminal.");
      return;
    }
    if (disposedRef.current) return;

    // 2. Build the terminal.
    const [{ Terminal }, { FitAddon }] = await Promise.all([
      import("@xterm/xterm"),
      import("@xterm/addon-fit"),
    ]);
    if (disposedRef.current || !hostRef.current) return;

    const term = new Terminal({
      cursorBlink: true,
      fontFamily:
        'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace',
      fontSize: 13,
      theme: { background: "#0a0e1a", foreground: "#e2e8f0", cursor: "#e2e8f0" },
    });
    const fit = new FitAddon();
    term.loadAddon(fit);
    term.open(hostRef.current);
    try {
      fit.fit();
    } catch {
      /* ignore */
    }
    termRef.current = term;
    fitRef.current = fit;

    // 3. Open the websocket to the PTY backend (nginx proxies /terminal-ws).
    const scheme = location.protocol === "https:" ? "wss" : "ws";
    const ws = new WebSocket(
      `${scheme}://${location.host}/terminal-ws?token=${encodeURIComponent(token)}`
    );
    ws.binaryType = "arraybuffer";
    wsRef.current = ws;

    ws.onopen = () => {
      setStatus("connected");
      term.focus();
      sendResize();
    };
    ws.onmessage = (ev) => {
      if (typeof ev.data === "string") {
        term.write(ev.data);
      } else if (ev.data instanceof ArrayBuffer) {
        term.write(new Uint8Array(ev.data));
      }
    };
    ws.onerror = () => {
      setError("Connection error.");
    };
    ws.onclose = (ev) => {
      setStatus((s) => (s === "error" ? s : "closed"));
      if (ev.reason && termRef.current) {
        term.write(`\r\n\x1b[90m[${ev.reason}]\x1b[0m\r\n`);
      }
    };

    // 4. Keystrokes → server.
    term.onData((data) => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify({ type: "data", data }));
      }
    });

    // 5. Keep the PTY window sized to the panel.
    const ro = new ResizeObserver(() => sendResize());
    if (hostRef.current) ro.observe(hostRef.current);
    roRef.current = ro;
  }

  function disconnect() {
    teardown();
    setStatus("closed");
  }

  const statusLabel: Record<Status, string> = {
    idle: "Not connected",
    connecting: "Connecting…",
    connected: "Connected",
    closed: "Disconnected",
    error: "Error",
  };
  const statusColor: Record<Status, string> = {
    idle: "bg-slate-500",
    connecting: "bg-amber-400 animate-pulse",
    connected: "bg-emerald-400",
    closed: "bg-slate-500",
    error: "bg-red-500",
  };
  const live = status === "connected" || status === "connecting";

  if (!mounted) return null;

  return createPortal(
    <div className="fixed inset-0 z-[70] flex justify-end" role="dialog" aria-modal="true">
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={onClose}
        aria-hidden
      />

      {/* Slide-in panel */}
      <div className="relative flex h-full w-full max-w-3xl flex-col border-l border-white/10 bg-navy-900 shadow-2xl md:w-1/2">
        {/* Header */}
        <div className="flex flex-none items-center gap-3 border-b border-white/[0.06] px-4 py-3">
          <div className="flex items-center gap-2">
            <span className={`h-2.5 w-2.5 rounded-full ${statusColor[status]}`} />
            <span className="text-sm font-semibold text-white">Terminal</span>
            <span className="text-xs text-slate-400">{statusLabel[status]}</span>
          </div>

          <div className="ml-auto flex items-center gap-2">
            <select
              value={serverId}
              onChange={(e) => setServerId(e.target.value)}
              disabled={live}
              className="max-w-[10rem] rounded-lg border border-white/10 bg-white/5 px-2.5 py-1.5 text-xs text-white outline-none focus:border-brand-400/60 disabled:opacity-50"
            >
              {servers.length === 0 && <option value="">No running servers</option>}
              {servers.map((s) => (
                <option key={s.id} value={s.id} className="bg-navy-900">
                  {s.hostname}
                </option>
              ))}
            </select>

            {live ? (
              <button
                onClick={disconnect}
                className="rounded-lg border border-white/10 bg-white/5 px-3 py-1.5 text-xs font-semibold text-slate-200 hover:bg-white/10"
              >
                Disconnect
              </button>
            ) : (
              <button
                onClick={connect}
                disabled={!serverId}
                className="rounded-lg bg-brand-500 px-3 py-1.5 text-xs font-semibold text-white hover:bg-brand-400 disabled:opacity-50"
              >
                Connect
              </button>
            )}

            <button
              onClick={onClose}
              className="rounded-lg p-1.5 text-slate-400 hover:bg-white/10 hover:text-white"
              aria-label="Close terminal"
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                <path d="M18 6 6 18M6 6l12 12" />
              </svg>
            </button>
          </div>
        </div>

        {/* Error banner */}
        {error && (
          <div className="flex-none border-b border-red-500/20 bg-red-500/10 px-4 py-2 text-xs text-red-200">
            {error}
          </div>
        )}

        {/* Hint before first connect */}
        {status === "idle" && (
          <div className="flex-none border-b border-white/[0.06] bg-white/[0.02] px-4 py-2 text-xs text-slate-400">
            {selected
              ? <>Opens a root shell on <span className="font-semibold text-slate-200">{selected.hostname}</span>. Run <code className="rounded bg-white/10 px-1 text-slate-200">claude</code> to start building.</>
              : "Pick a running server, then press Connect."}
          </div>
        )}

        {/* Terminal surface */}
        <div className="min-h-0 flex-1 bg-[#0a0e1a] p-2">
          <div ref={hostRef} className="h-full w-full" />
        </div>
      </div>
    </div>,
    document.body
  );
}

